// ─────────────────────────────────────────────────────────────────────────
// QUO (OpenPhone) — business calling & texting hub.
// All Quo API traffic goes through the quo-proxy edge function; the API key
// lives only as a server-side secret and never enters this public bundle.
// ─────────────────────────────────────────────────────────────────────────
async function quoCall(path, { method = 'GET', query, body } = {}) {
  const { data, error } = await supabase.functions.invoke('quo-proxy', { body: { path, method, query, body } });
  if (error) throw new Error(error.message || 'quo-proxy unreachable');
  if (!data) throw new Error('No response from Quo');
  if (data.ok === false && data.error) throw new Error(data.error);
  if (typeof data.status === 'number' && data.status >= 400) {
    const d = data.data || {};
    throw new Error(d.message || d.errors?.[0]?.message || `Quo error ${data.status}`);
  }
  return data.data; // { data: [...] } | { data: {...} }
}
function quoNormPhone(raw) {
  if (!raw) return '';
  const d = String(raw).replace(/[^\d]/g, '');
  if (raw.toString().trim().startsWith('+')) return '+' + d;
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d[0] === '1') return '+' + d;
  return d ? '+' + d : '';
}
function quoFmtPhone(e164) {
  if (!e164) return '';
  const d = String(e164).replace(/[^\d]/g, '');
  if (d.length === 11 && d[0] === '1') return `(${d.slice(1,4)}) ${d.slice(4,7)}-${d.slice(7)}`;
  if (d.length === 10) return `(${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}`;
  return e164;
}
function quoLast10(raw) { return String(raw || '').replace(/[^\d]/g, '').slice(-10); }
function quoFmtWhen(ts) {
  if (!ts) return '';
  const d = new Date(ts), now = new Date();
  const sameDay = d.toDateString() === now.toDateString();
  if (sameDay) return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  const yest = new Date(now); yest.setDate(now.getDate() - 1);
  if (d.toDateString() === yest.toDateString()) return 'Yesterday';
  return d.toLocaleDateString([], { month: 'short', day: 'numeric' });
}
function quoFmtDur(sec) {
  if (!sec && sec !== 0) return '';
  const m = Math.floor(sec / 60), s = sec % 60;
  return m ? `${m}m ${s}s` : `${s}s`;
}

function QuoCallDetail({ callId }) {
  const [summary, setSummary] = useState(null);
  const [transcript, setTranscript] = useState(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState('');
  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const [s, t] = await Promise.allSettled([
          quoCall(`/v1/call-summaries/${callId}`),
          quoCall(`/v1/call-transcripts/${callId}`),
        ]);
        if (!alive) return;
        if (s.status === 'fulfilled') setSummary(s.value?.data || null);
        if (t.status === 'fulfilled') setTranscript(t.value?.data || null);
      } catch (e) { if (alive) setErr(String(e.message || e)); }
      finally { if (alive) setLoading(false); }
    })();
    return () => { alive = false; };
  }, [callId]);
  if (loading) return <div style={{ fontSize: 12, color: 'var(--text-3)', padding: '6px 0' }}>Loading call details…</div>;
  const sum = summary?.summary;
  const steps = summary?.nextSteps;
  const dialogue = transcript?.dialogue;
  if (!sum && !(steps && steps.length) && !(dialogue && dialogue.length)) {
    return <div style={{ fontSize: 12, color: 'var(--text-3)', padding: '6px 0' }}>No summary or transcript available (Business/Scale plan feature, or still processing).</div>;
  }
  return (
    <div style={{ marginTop: 8, borderTop: '1px solid var(--border)', paddingTop: 8, display: 'flex', flexDirection: 'column', gap: 8 }}>
      {sum && (<div><div style={{ fontSize: 11, fontWeight: 700, color: 'var(--accent)', marginBottom: 3 }}>AI SUMMARY</div><div style={{ fontSize: 13, color: 'var(--text-1)', lineHeight: 1.5 }}>{sum}</div></div>)}
      {Array.isArray(steps) && steps.length > 0 && (<div><div style={{ fontSize: 11, fontWeight: 700, color: 'var(--accent)', marginBottom: 3 }}>NEXT STEPS</div><ul style={{ margin: 0, paddingLeft: 18, fontSize: 13, color: 'var(--text-1)' }}>{steps.map((x, i) => <li key={i}>{typeof x === 'string' ? x : x.text || JSON.stringify(x)}</li>)}</ul></div>)}
      {Array.isArray(dialogue) && dialogue.length > 0 && (
        <div><div style={{ fontSize: 11, fontWeight: 700, color: 'var(--accent)', marginBottom: 3 }}>TRANSCRIPT</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4, maxHeight: 220, overflowY: 'auto' }}>
            {dialogue.map((seg, i) => (
              <div key={i} style={{ fontSize: 12.5, lineHeight: 1.45 }}>
                <span style={{ fontWeight: 700, color: 'var(--text-2)' }}>{seg.identifier || seg.speaker || 'Speaker'}: </span>
                <span style={{ color: 'var(--text-1)' }}>{seg.content || seg.text || ''}</span>
              </div>
            ))}
          </div>
        </div>
      )}
      {err && <div style={{ fontSize: 12, color: 'var(--red)' }}>{err}</div>}
    </div>
  );
}

// Compact, self-loading live feed of Quo activity (messages + calls), used both
// inside the Quo module and on the Systems board. Subscribes to realtime so new
// texts and calls appear the instant the webhook lands.
const today_ymd = () => new Date().toISOString().slice(0, 10);

// ─── FinanceView — root component ────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════
// PROSPECTING — top-level tab. The daily money-making engine: gamified
// "Today" board, the activated lead-gen systems, and the 85-system library.
// ═══════════════════════════════════════════════════════════════════════

function useDictation(onFinal) {
  const [recording, setRecording] = useState(false);
  const [interim, setInterim] = useState('');
  const recRef = useRef(null);
  const wantRef = useRef(false);      // does the user still want to be listening?
  const timerRef = useRef(null);      // pending auto-restart
  const startedAtRef = useRef(0);
  const failsRef = useRef(0);         // consecutive fast failures (runaway guard)
  const onFinalRef = useRef(onFinal);
  useEffect(() => { onFinalRef.current = onFinal; });
  const supported = typeof window !== 'undefined' && !!(window.SpeechRecognition || window.webkitSpeechRecognition);

  const teardown = useCallback(() => {
    if (timerRef.current) { clearTimeout(timerRef.current); timerRef.current = null; }
    const r = recRef.current; recRef.current = null;
    if (r) { try { r.onresult = r.onerror = r.onend = null; } catch (_) {} try { r.abort(); } catch (_) {} }
  }, []);

  const launch = useCallback(() => {
    const SR = typeof window !== 'undefined' && (window.SpeechRecognition || window.webkitSpeechRecognition);
    if (!SR) return;
    teardown(); // never leave a previous recognizer holding the mic
    let rec; try { rec = new SR(); } catch (_) { return; }
    rec.lang = 'en-US'; rec.continuous = true; rec.interimResults = true;
    rec.onresult = (ev) => {
      let f = '', it = '';
      for (let i = ev.resultIndex; i < ev.results.length; i++) { const r = ev.results[i]; if (r.isFinal) f += r[0].transcript; else it += r[0].transcript; }
      if (f) { failsRef.current = 0; if (onFinalRef.current) onFinalRef.current(f); }
      setInterim(it);
    };
    rec.onerror = (e) => {
      const err = e && e.error;
      // Fatal — stop for good. (no-speech / aborted / network are transient; let onend auto-restart.)
      if (err === 'not-allowed' || err === 'service-not-allowed' || err === 'audio-capture') {
        wantRef.current = false; setRecording(false); setInterim('');
      }
    };
    rec.onend = () => {
      setInterim('');
      if (!wantRef.current) { setRecording(false); return; }
      // Mobile speech engines quietly end after a pause even with continuous=true.
      // Restart so dictation keeps going — but bail out if it's failing rapidly.
      const quick = (Date.now() - startedAtRef.current) < 600;
      failsRef.current = quick ? failsRef.current + 1 : 0;
      if (failsRef.current >= 5) { wantRef.current = false; setRecording(false); return; }
      timerRef.current = setTimeout(() => { if (wantRef.current) launch(); }, 300);
    };
    recRef.current = rec;
    startedAtRef.current = Date.now();
    try { rec.start(); setRecording(true); } catch (_) { /* already starting / busy */ }
  }, [teardown]);

  const start = useCallback(() => { wantRef.current = true; failsRef.current = 0; launch(); }, [launch]);
  const stop = useCallback(() => { wantRef.current = false; teardown(); setRecording(false); setInterim(''); }, [teardown]);
  useEffect(() => () => { wantRef.current = false; teardown(); }, [teardown]);
  return { recording, interim, start, stop, supported };
}

// Textarea that grows with its content (no inner scroll until maxHeight).
function QuickLog({ userId, onNavigate, onUploadRecording }) {
  const recRef = useRef(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [journalOpen, setJournalOpen] = useState(false);
  const [text, setText] = useState('');
  const [saving, setSaving] = useState(false);
  const dict = useDictation((f) => setText(prev => { const sep = (!prev || /\s$/.test(prev)) ? '' : ' '; return prev + sep + f.trim() + ' '; }));

  async function save() {
    const c = text.trim(); if (!c || saving) return;
    if (dict.recording) dict.stop();
    setSaving(true);
    try { await logJournalEntry(userId, c, dict.recording ? 'voice' : 'text'); setText(''); setJournalOpen(false); if (window.__notify) window.__notify('Logged to journal', 'success'); }
    catch (e) { if (window.__notify) window.__notify(e.message || 'Save failed — please try again. Your text is still here.', 'error'); }
    finally { setSaving(false); }
  }

  const go = (view) => { setMenuOpen(false); if (onNavigate) onNavigate(view); };
  const goQuo = (tab) => { try { window.__quoTab = tab; } catch (e) {} go('quo'); };
  const openJournal = () => { setMenuOpen(false); setJournalOpen(true); };

  // Listed in the user's order; rendered bottom-up (journal nearest the thumb).
  const MENU = [
    { key: 'journal', label: 'Journal entry',  icon: 'journal',   run: openJournal },
    { key: 'task',    label: 'Task',           icon: 'tasks',     run: () => go('tasks') },
    { key: 'event',   label: 'Calendar event', icon: 'calendar',  run: () => go('calendar') },
    { key: 'contact', label: 'Contact',        icon: 'contacts',  run: () => go('contacts') },
    { key: 'ari',     label: 'Ari request',    icon: 'briefing',  run: () => go('dashboard') },
    { key: 'text',    label: 'Text',           icon: 'message',   run: () => goQuo('messages') },
    { key: 'email',   label: 'Email',          icon: 'mail',      run: () => go('inbox') },
    { key: 'call',    label: 'Call · Quo',     icon: 'quo',       run: () => goQuo('calls') },
    { key: 'recording', label: 'Recording',    icon: 'mic',       run: () => { setMenuOpen(false); if (recRef.current) recRef.current.click(); } },
  ];

  return (
    <>
      <input ref={recRef} type="file" accept="audio/*,.amr,.m4a,.mp3,.wav,.aac,.ogg,.opus,.webm,.3gp" style={{ display: 'none' }}
        onChange={(e) => { const file = e.target.files && e.target.files[0]; e.target.value = ''; if (file && onUploadRecording) onUploadRecording(file); }} />
      {/* Floating quick-create menu */}
      {menuOpen && (
        <>
          <div onClick={() => setMenuOpen(false)}
            style={{ position: 'fixed', inset: 0, zIndex: 9000, background: 'rgba(0,0,0,0.28)', backdropFilter: 'blur(1px)' }} />
          <div style={{ position: 'fixed', right: '11px', bottom: 'calc(env(safe-area-inset-bottom, 0px) + 123px)', zIndex: 9001, display: 'flex', flexDirection: 'column-reverse', gap: '12px', alignItems: 'flex-end' }}>
            {MENU.map((m, i) => (
              <button key={m.key} onClick={m.run}
                style={{ display: 'flex', alignItems: 'center', gap: '10px', background: 'none', border: 'none', padding: 0, cursor: 'pointer', animation: 'qmRise 0.18s ease both', animationDelay: `${i * 0.03}s` }}>
                <span style={{ padding: '7px 12px', borderRadius: '999px', background: 'var(--bg-card)', border: '1px solid var(--border)', color: 'var(--text-1)', fontSize: '13px', fontWeight: 600, whiteSpace: 'nowrap', boxShadow: '0 4px 14px rgba(0,0,0,0.35)' }}>{m.label}</span>
                <span style={{ width: '42px', height: '42px', borderRadius: '50%', background: 'var(--bg-card)', border: '1px solid var(--accent)', color: 'var(--accent)', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 4px 14px rgba(0,0,0,0.4)', flexShrink: 0 }}>
                  <Icon name={m.icon} size={19} />
                </span>
              </button>
            ))}
          </div>
        </>
      )}

      {/* FAB — memory icon, 40% smaller, toggles the menu */}
      <button onClick={() => setMenuOpen(o => !o)} aria-label={menuOpen ? 'Close quick create' : 'Quick create'} title="Quick create"
        style={{ position: 'fixed', right: '16px', bottom: 'calc(env(safe-area-inset-bottom, 0px) + 78px)', zIndex: 9002, width: '33px', height: '33px', borderRadius: '50%', background: 'var(--accent)', color: 'var(--bg-base)', border: 'none', boxShadow: '0 6px 20px rgba(0,0,0,0.45)', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'transform 0.18s ease', transform: menuOpen ? 'rotate(90deg)' : 'none' }}>
        {menuOpen ? <span style={{ fontSize: '16px', fontWeight: 700, lineHeight: 1 }}>✕</span> : <Icon name="brain" size={17} />}
      </button>

      {journalOpen && (
        <div className="modal-backdrop" onClick={(e) => { if (e.target === e.currentTarget) setJournalOpen(false); }} style={{ padding: '12px' }}>
          <div className="modal" style={{ maxWidth: 'none', width: 'min(760px, 100%)', height: 'min(92vh, 100%)', maxHeight: 'none', padding: '18px', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', flexShrink: 0 }}>
              <h3 style={{ margin: 0, fontSize: '16px', display:'inline-flex', alignItems:'center', gap:'7px' }}><Icon name="journal" size={16} /> Quick log</h3>
              <button onClick={() => setJournalOpen(false)} style={{ background: 'none', border: 'none', fontSize: '22px', color: 'var(--text-3)', cursor: 'pointer', lineHeight: 1 }}>×</button>
            </div>
            <textarea autoFocus value={text + (dict.interim ? ((text && !/\s$/.test(text)) ? ' ' : '') + dict.interim : '')} onChange={e => setText(e.target.value)} placeholder="Capture a moment — it'll timestamp and auto-link…"
              style={{ flex: 1, minHeight: 0, width: '100%', padding: '15px', background: 'var(--bg-base)', border: '1px solid var(--border)', borderRadius: '10px', color: 'var(--text-1)', fontSize: '16px', boxSizing: 'border-box', lineHeight: 1.6, resize: 'none', fontFamily: 'inherit' }} />
            <div style={{ display: 'flex', gap: '8px', marginTop: '12px', alignItems: 'center', flexShrink: 0 }}>
              {dict.supported && <button onClick={() => dict.recording ? dict.stop() : dict.start()} style={{ padding: '10px 16px', borderRadius: '999px', border: `1px solid ${dict.recording ? 'var(--red)' : 'var(--border)'}`, background: dict.recording ? 'rgba(239,68,68,0.12)' : 'var(--bg-hover)', color: dict.recording ? 'var(--red)' : 'var(--text-2)', cursor: 'pointer', fontSize: '13px', fontWeight: 700 }}>{dict.recording ? <>⏹ Recording…</> : <><Icon name="mic" size={13} /> Voice</>}</button>}
              <span style={{ flex: 1 }} />
              <button onClick={save} disabled={saving || !text.trim()} style={{ padding: '10px 24px', background: 'var(--accent)', color: 'var(--bg-base)', border: 'none', borderRadius: '999px', fontWeight: 800, fontSize: '14px', cursor: 'pointer', opacity: (saving || !text.trim()) ? 0.5 : 1 }}>{saving ? '…' : 'Log'}</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

function EmailAccountsPanel({ emailAccounts, setEmailAccounts }) {
  const [connecting, setConnecting] = useState(false);
  const [connectingPurpose, setConnectingPurpose] = useState(null);
  const [err, setErr] = useState('');

  async function startConnect(purpose = 'email', loginHint = '') {
    setConnecting(true);
    setConnectingPurpose(purpose);
    setErr('');
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) throw new Error('Not signed in.');
      const { data, error } = await supabase.functions.invoke('google-oauth-start', {
        body: { return_to: window.location.origin + window.location.pathname, purpose, login_hint: loginHint },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error + (data.details ? ` — ${data.details}` : ''));
      if (!data?.url) throw new Error('No URL returned.');
      window.location.href = data.url;
    } catch (e) {
      setErr(e.message || String(e));
      setConnecting(false);
      setConnectingPurpose(null);
    }
  }

  async function disconnect(id) {
    if (!await confirmDialog('Disconnect this Google account? Synced messages and events will remain in the database, but future sync will stop.')) return;
    await supabase.from('email_accounts').update({ is_active: false }).eq('id', id);
    setEmailAccounts(prev => prev.map(a => a.id === id ? { ...a, is_active: false } : a));
  }

  function purposeBadges(purposes) {
    const list = purposes || [];
    return list.map(p => (
      <span key={p} className="pill" style={{
        fontSize:'10px', padding:'2px 6px',
        background: p === 'calendar' ? 'rgba(197,169,94,0.15)' : 'rgba(34,197,94,0.12)',
        color: p === 'calendar' ? 'var(--accent)' : 'var(--green)',
        border: `1px solid ${p === 'calendar' ? 'var(--accent-dim)' : '#22c55e'}`,
      }}>{p === 'calendar' ? <><Icon name="calendar" size={12} /> calendar</> : <><Icon name="mail" size={12} /> email</>}</span>
    ));
  }

  return (
    <div className="panel" style={{marginBottom:'18px'}}>
      <div className="panel-header"><h3><span style={{display:'inline-flex',alignItems:'center',gap:'6px'}}><Icon name="link" size={15} /> Connected Google Accounts</span></h3></div>
      <div className="panel-body">
        <p style={{fontSize:'13px',color:'var(--text-2)',margin:'0 0 14px',lineHeight:1.5}}>
          Connect Google for email (Gmail) and/or calendar. You can connect different accounts for different purposes — for example, a work account for email and a personal account for calendar.
        </p>
        {emailAccounts.length === 0
          ? <p style={{fontSize:'13px',color:'var(--text-3)',marginBottom:'14px'}}>No accounts connected yet.</p>
          : (
            <div style={{display:'flex',flexDirection:'column',gap:'8px',marginBottom:'14px'}}>
              {emailAccounts.map(a => (
                <div key={a.id} style={{padding:'10px 12px',background:'var(--bg-base)',border:'1px solid var(--border)',borderRadius:'8px',display:'flex',alignItems:'center',gap:'10px',flexWrap:'wrap'}}>
                  <span style={{fontSize:'18px'}}>{(a.purposes||[]).includes('calendar') ? <Icon name="calendar" size={16} /> : <Icon name="mail" size={16} />}</span>
                  <div style={{flex:1,minWidth:'160px'}}>
                    <div style={{fontWeight:600,color:'var(--text-1)',fontSize:'14px',display:'flex',alignItems:'center',gap:'6px',flexWrap:'wrap'}}>
                      {a.email_address}
                      {purposeBadges(a.purposes)}
                    </div>
                    <div style={{fontSize:'12px',color:'var(--text-2)'}}>
                      {a.provider} · {a.is_active ? 'active' : 'inactive'}
                      {a.last_sync_at && <> · synced {new Date(a.last_sync_at).toLocaleString()}</>}
                    </div>
                    {a.last_sync_error === 'REAUTH_REQUIRED' ? (
                      <div style={{marginTop:'6px',padding:'8px 10px',background:'rgba(245,158,11,0.12)',border:'1px solid var(--yellow)',borderRadius:'8px'}}>
                        <div style={{fontSize:'12px',color:'var(--yellow)',fontWeight:600,marginBottom:'6px'}}>⚠ Google ended this connection — reconnect to resume sync.</div>
                        <button className="btn btn-sm" style={{background:'var(--yellow)',color:'#1a1205',fontWeight:600}} disabled={connecting}
                          onClick={()=>startConnect((a.purposes||[]).includes('calendar') ? 'calendar' : 'email')}>
                          {connecting ? 'Opening Google…' : 'Reconnect now'}
                        </button>
                      </div>
                    ) : a.last_sync_error && (
                      <div style={{fontSize:'12px',color:'var(--red)',marginTop:'2px'}}>Last error: {a.last_sync_error.slice(0, 200)}</div>
                    )}
                  </div>
                  {a.is_active && (
                    <div style={{display:'flex',gap:'6px',flexWrap:'wrap'}}>
                      {!(a.purposes||[]).includes('calendar') && (a.scopes||[]).every(s=>!s.includes('calendar')) && (
                        <button className="btn btn-sm" disabled={connecting}
                          style={{background:'var(--accent)',color:'#1a1205',fontWeight:600}}
                          onClick={()=>startConnect('calendar', a.email_address)}
                          title={`Grant calendar access to ${a.email_address}`}>
                          {connecting && connectingPurpose === 'calendar' ? 'Opening Google…' : <><Icon name="calendar" size={13} /> Add Calendar</>}
                        </button>
                      )}
                      <button className="btn btn-ghost btn-sm" onClick={()=>disconnect(a.id)}>Disconnect</button>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )
        }
        {err && (
          <div style={{padding:'10px 12px',background:'rgba(239, 68, 68, 0.1)',border:'1px solid var(--red)',borderRadius:'8px',color:'var(--red)',fontSize:'13px',marginBottom:'12px'}}>
            {err}
          </div>
        )}
        <div style={{display:'flex',gap:'8px',flexWrap:'wrap'}}>
          <button className="btn btn-primary" onClick={() => startConnect('email')} disabled={connecting}>
            {connecting && connectingPurpose === 'email' ? 'Opening Google…' : '+ Connect Gmail'}
          </button>
          <button className="btn btn-ghost" onClick={() => startConnect('calendar')} disabled={connecting} style={{borderColor:'var(--accent-dim)',color:'var(--accent)'}}>
            {connecting && connectingPurpose === 'calendar' ? 'Opening Google…' : '+ Connect Calendar'}
          </button>
        </div>
      </div>
    </div>
  );
}


// ─────────────────────────────────────────
// SETTINGS VIEW
function EmailAliasesPanel({ emailAliases, setEmailAliases, emailAccounts, userId }) {
  const [syncing, setSyncing] = useState(false);
  const [busy, setBusy] = useState(null);   // alias id currently being updated
  const [editingName, setEditingName] = useState(null);  // {id, value}
  const [msg, setMsg] = useState(null);

  // The email-purpose Google account (only it has a sendAs list)
  const emailAccount =
    emailAccounts.find(a => a.is_active && (a.purposes || []).includes('email')) ||
    emailAccounts.find(a => a.is_active && (a.scopes || []).some(s => s.includes('gmail')));

  const aliases = (emailAliases || []).slice().sort((a, b) => {
    if (a.is_default !== b.is_default) return a.is_default ? -1 : 1;
    if (a.is_primary !== b.is_primary) return a.is_primary ? -1 : 1;
    return a.email_address.localeCompare(b.email_address);
  });

  function flash(text, type = 'ok') {
    setMsg({ text, type });
    setTimeout(() => setMsg(null), 4000);
  }

  async function syncAliases() {
    if (!emailAccount) { flash('Connect a Gmail account first.', 'error'); return; }
    setSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke('gmail-aliases-sync', {
        body: { user_id: userId, account_id: emailAccount.id }
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      const { data: fresh } = await supabase.from('email_aliases').select('*').order('email_address', { ascending: true });
      if (fresh) setEmailAliases(fresh);
      flash(`Synced ${data.synced} sender ${data.synced === 1 ? 'address' : 'addresses'} from Gmail.`);
    } catch (e) {
      flash('Sync failed: ' + (e.message || e), 'error');
    } finally {
      setSyncing(false);
    }
  }

  async function setDefault(alias) {
    if (alias.is_default) return;
    setBusy(alias.id);
    try {
      // The DB trigger clears is_default on other rows when we set this one.
      const { error } = await supabase.from('email_aliases').update({ is_default: true }).eq('id', alias.id);
      if (error) throw error;
      setEmailAliases(prev => prev.map(a => ({ ...a, is_default: a.id === alias.id })));
      flash(`Default sender set to ${alias.email_address}.`);
    } catch (e) {
      flash('Failed: ' + (e.message || e), 'error');
    } finally {
      setBusy(null);
    }
  }

  async function saveName(alias, newName) {
    const cleaned = (newName || '').trim();
    if (cleaned === (alias.display_name || '')) {
      setEditingName(null);
      return;
    }
    setBusy(alias.id);
    try {
      const { error } = await supabase.from('email_aliases').update({ display_name: cleaned || null }).eq('id', alias.id);
      if (error) throw error;
      setEmailAliases(prev => prev.map(a => a.id === alias.id ? { ...a, display_name: cleaned || null } : a));
      flash(`Display name updated for ${alias.email_address}.`);
      setEditingName(null);
    } catch (e) {
      flash('Failed: ' + (e.message || e), 'error');
    } finally {
      setBusy(null);
    }
  }

  return (
    <div className="panel" style={{marginBottom:'18px'}}>
      <div className="panel-header" style={{justifyContent:'space-between'}}>
        <h3 style={{display:'inline-flex',alignItems:'center',gap:'7px'}}><Icon name="mail" size={15} /> Sender Addresses</h3>
        <button className="btn btn-ghost btn-sm" onClick={syncAliases} disabled={syncing || !emailAccount}>
          {syncing ? '↻ Syncing…' : '↻ Sync from Gmail'}
        </button>
      </div>
      <div className="panel-body">
        <p style={{fontSize:'13px',color:'var(--text-2)',margin:'0 0 14px',lineHeight:1.5}}>
          These are the addresses you can send mail "From" inside Prism. They mirror the <strong>Send mail as</strong> list in your Gmail Settings. The address marked <strong style={{color:'var(--accent)'}}>default</strong> is pre-selected in Compose; replies override it to match whatever address the original was sent to.
        </p>

        {msg && (
          <div style={{padding:'10px 12px',marginBottom:'12px',borderRadius:'6px',fontSize:'12px',
            background: msg.type === 'ok' ? 'rgba(34,197,94,0.12)' : 'rgba(239,68,68,0.12)',
            border: `1px solid ${msg.type === 'ok' ? '#22c55e' : '#ef4444'}`,
            color: msg.type === 'ok' ? '#22c55e' : '#ef4444'}}>{msg.text}</div>
        )}

        {!emailAccount && (
          <div style={{padding:'12px',background:'var(--bg-base)',border:'1px dashed var(--border)',borderRadius:'8px',fontSize:'12px',color:'var(--text-3)'}}>
            Connect a Gmail account above first — sender addresses are pulled from that account's Gmail Settings.
          </div>
        )}

        {emailAccount && aliases.length === 0 && (
          <div style={{padding:'12px',background:'var(--bg-base)',border:'1px dashed var(--border)',borderRadius:'8px',fontSize:'12px',color:'var(--text-3)'}}>
            No sender addresses synced yet. Click <strong>Sync from Gmail</strong> above.
          </div>
        )}

        {aliases.length > 0 && (
          <div style={{display:'flex',flexDirection:'column',gap:'8px'}}>
            {aliases.map(a => {
              const isEditing = editingName?.id === a.id;
              return (
                <div key={a.id} style={{
                  padding:'12px',
                  background: a.is_default ? 'var(--accent-glow)' : 'var(--bg-base)',
                  border: `1px solid ${a.is_default ? 'var(--accent-dim)' : 'var(--border)'}`,
                  borderRadius:'8px',
                  display:'flex', alignItems:'center', gap:'10px', flexWrap:'wrap'
                }}>
                  <div style={{flex:1, minWidth:'200px'}}>
                    <div style={{display:'flex',alignItems:'center',gap:'8px',flexWrap:'wrap',marginBottom:'4px'}}>
                      <span style={{fontWeight:600,color:'var(--text-1)',fontSize:'14px'}}>{a.email_address}</span>
                      {a.is_default && <span className="pill" style={{fontSize:'10px',padding:'2px 6px',background:'var(--accent)',color:'var(--bg-base)',fontWeight:700}}>DEFAULT</span>}
                      {a.is_primary && <span className="pill" style={{fontSize:'10px',padding:'2px 6px',background:'var(--bg-card)',color:'var(--text-2)',border:'1px solid var(--border)'}}>primary</span>}
                      {!a.verified && <span className="pill" style={{fontSize:'10px',padding:'2px 6px',background:'rgba(239,68,68,0.15)',color:'var(--red)',border:'1px solid var(--red)'}}>unverified</span>}
                    </div>
                    {isEditing ? (
                      <div style={{display:'flex',gap:'4px',alignItems:'center'}}>
                        <input
                          className="form-input"
                          autoFocus
                          value={editingName.value}
                          onChange={e => setEditingName({ ...editingName, value: e.target.value })}
                          onKeyDown={e => {
                            if (e.key === 'Enter') { e.preventDefault(); saveName(a, editingName.value); }
                            if (e.key === 'Escape') setEditingName(null);
                          }}
                          placeholder="Display name (e.g. Your Name)"
                          style={{padding:'4px 8px',fontSize:'12px',height:'auto'}}
                        />
                        <button className="btn btn-ghost btn-sm" onClick={() => saveName(a, editingName.value)} disabled={busy === a.id} style={{padding:'4px 8px',fontSize:'11px'}}>Save</button>
                        <button className="btn btn-ghost btn-sm" onClick={() => setEditingName(null)} style={{padding:'4px 8px',fontSize:'11px'}}>×</button>
                      </div>
                    ) : (
                      <div style={{fontSize:'12px',color:'var(--text-3)',display:'flex',alignItems:'center',gap:'6px'}}>
                        <span>{a.display_name || <em style={{opacity:0.6}}>no display name</em>}</span>
                        <button onClick={() => setEditingName({ id: a.id, value: a.display_name || '' })} style={{background:'none',border:'none',color:'var(--accent)',cursor:'pointer',fontSize:'11px',padding:0}}>edit</button>
                      </div>
                    )}
                  </div>
                  {!a.is_default && a.verified && (
                    <button className="btn btn-ghost btn-sm" onClick={() => setDefault(a)} disabled={busy === a.id}
                      style={{borderColor:'var(--accent-dim)',color:'var(--accent)',fontSize:'11px'}}>
                      {busy === a.id ? '…' : 'Set as default'}
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        )}

        <p style={{fontSize:'11px',color:'var(--text-3)',marginTop:'14px',lineHeight:1.5}}>
          To add or remove an alias, change it in <a href="https://mail.google.com/mail/u/0/#settings/accounts" target="_blank" rel="noreferrer" style={{color:'var(--accent)'}}>Gmail Settings → Accounts → Send mail as</a>, then click Sync from Gmail above.
        </p>
      </div>
    </div>
  );
}

